import fs from 'node:fs';
import path from 'node:path';

const payload = {"src/App.tsx":"","src/auth/AuthContext.tsx":"","src/auth/AuthScreen.tsx":"","src/components/UI.tsx":"","src/data/seed.json":"","src/lib/cloud.ts":"","src/lib/storage.ts":"","src/lib/supabase.ts":"","src/main.tsx":"","src/styles.css":"","src/types.ts":"","src/views/Capacity.tsx":"","src/views/ChangeManagement.css":"","src/views/ChangeManagement.tsx":"","src/views/Dashboard.tsx":"","src/views/Decisions.tsx":"","src/views/Helpdesk.css":"","src/views/Helpdesk.tsx":"","src/views/IamManagement.css":"","src/views/IamManagement.tsx":"","src/views/People.tsx":"","src/views/ProblemManagement.css":"","src/views/ProblemManagement.tsx":"","src/views/Raci.css":"","src/views/Raci.tsx":"","src/views/Risks.tsx":"","src/views/Roadmap.tsx":"","src/views/Services.tsx":"","src/views/Substitutions.tsx":"","src/views/Users.tsx":"","src/views/Work.css":"","src/views/Work.tsx":"","package.json":""};
const cwd = process.cwd();
const packagePath = path.join(cwd, 'package.json');
if (!fs.existsSync(packagePath)) {
  console.error('CHYBA: Spusti tento skript v koreni StackBlitz projektu vedla package.json.');
  process.exit(1);
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupRoot = path.join(cwd, `backup-pred-komplet-fix-08d-${stamp}`);
fs.mkdirSync(backupRoot, { recursive: true });

const srcPath = path.join(cwd, 'src');
if (fs.existsSync(srcPath)) {
  fs.cpSync(srcPath, path.join(backupRoot, 'src'), { recursive: true });
}
if (fs.existsSync(packagePath)) {
  fs.copyFileSync(packagePath, path.join(backupRoot, 'package.json'));
}

// Odstráni starý src, aby v projekte nezostali nekompatibilné súbory z predošlých releasov.
fs.rmSync(srcPath, { recursive: true, force: true });

for (const [relativePath, encoded] of Object.entries(payload)) {
  const target = path.join(cwd, relativePath);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, Buffer.from(encoded, 'base64'));
}

const required = [
  ['src/App.tsx', 'Change management'],
  ['src/App.tsx', 'Problem management'],
  ['src/App.tsx', 'IAM / Prístupy'],
  ['src/views/ChangeManagement.tsx', 'export default'],
  ['src/views/ProblemManagement.tsx', 'export default'],
  ['src/views/IamManagement.tsx', 'export default'],
  ['src/components/UI.tsx', "'change'"],
  ['src/components/UI.tsx', "'problem'"],
  ['src/components/UI.tsx', "'iam'"],
];

let ok = true;
for (const [relativePath, needle] of required) {
  const target = path.join(cwd, relativePath);
  const content = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
  if (!content.includes(needle)) {
    console.error(`CHYBA: ${relativePath} neobsahuje kontrolny text: ${needle}`);
    ok = false;
  } else {
    console.log(`OK: ${relativePath} -> ${needle}`);
  }
}

if (!ok) {
  console.error('Oprava nebola kompletna. Povodne subory su v:', backupRoot);
  process.exit(1);
}

console.log('');
console.log('HOTOVO: Kompletny zdrojovy priecinok src bol nahradeny konzistentnou verziou 0.8.');
console.log('ZALOHA:', backupRoot);
console.log('DALEJ SPUST: npm run dev');
console.log('A POTOM OBNOV NAHLAD: Ctrl + F5');
console.log('PRIAME CESTY: #/changes, #/problems, #/iam');
